#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "atax.h"

/* Include the Exo-generated kernel header. */
#include "generated/atax/atax.h"


/* Array initialization. */
static
void init_array (int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n))
{
  int i, j;
  DATA_TYPE fn;
  fn = (DATA_TYPE)n;

  for (i = 0; i < n; i++)
      x[i] = 1 + (i / fn);
  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++)
      A[i][j] = (DATA_TYPE) ((i+j) % n) / (5*m);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(y,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("y");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, y[i]);
  }
  POLYBENCH_DUMP_END("y");
  POLYBENCH_DUMP_FINISH;
}

/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

@proc
def kernel_atax(
    m: size,
    n: size,
    A: DATA_TYPE[m, n] @ DRAM,
    x: DATA_TYPE[n] @ DRAM,
    y: DATA_TYPE[n] @ DRAM,
    tmp: DATA_TYPE[m] @ DRAM,
):
    # Base algorithm:
    #   tmp[i] = sum_j A[i, j] * x[j]
    #   y[j]   = sum_i A[i, j] * tmp[i]

    # Initialize y to zero
    for j in seq(0, n):
        y[j] = 0.0

    # Initialize tmp to zero
    for i in seq(0, m):
        tmp[i] = 0.0

    # Compute tmp = A * x (matrix–vector multiply, row-wise over A)
    for i in seq(0, m):
        for j in seq(0, n):
            tmp[i] += A[i, j] * x[j]

    # Compute y = A^T * tmp.
    # In the base version this traverses A column-wise (j outer, i inner),
    # which we will later reorder for better locality.
    for j in seq(0, n):
        for i in seq(0, m):
            y[j] += A[i, j] * tmp[i]


# ---------------- Scheduling for performance ----------------

# 1. Fuse the tmp initialization and tmp compute loops.
#    This ensures each row i of A is streamed once while we both zero
#    and accumulate tmp[i], improving temporal locality on tmp.
i_init = kernel_atax.find_loop("i #0")
i_compute = kernel_atax.find_loop("i #1")
kernel_atax = fuse(kernel_atax, i_init, i_compute)

# 2. Reorder the loops in the y-update phase to iterate row-major over A.
#    We transform:
#        for j in 0..n:
#          for i in 0..m:
#            y[j] += A[i, j] * tmp[i]
#    into:
#        for i in 0..m:
#          for j in 0..n:
#            y[j] += A[i, j] * tmp[i]
#    This streams through rows of A and contiguous elements of y,
#    greatly improving cache behavior on A while preserving the math:
#    additions are associative, so reordering the iteration space is safe.
update_outer_j = kernel_atax.find_loop("j #2")
kernel_atax = reorder_loops(kernel_atax, update_outer_j)

# 3. Parallelize the fused tmp loop over rows of A.
#    Each iteration i only reads A[i, :], x[:] and writes tmp[i], so
#    there are no cross-iteration dependencies and the loop is safe
#    to parallelize across cores (e.g., via OpenMP in the backend).
tmp_fused_i = kernel_atax.find_loop("i #0")
kernel_atax = parallelize_loop(kernel_atax, tmp_fused_i)

# 4. Simplify to clean up any incidental complexity introduced by rewrites.
kernel_atax = simplify(kernel_atax)

EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, M, N, m, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(tmp, DATA_TYPE, M, m);

  /* Initialize array(s). */
  init_array (m, n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(x));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten views to raw pointers. */
  kernel_atax (/*ctxt=*/NULL, m, n,
               (DATA_TYPE*)POLYBENCH_ARRAY(A),
               (DATA_TYPE*)POLYBENCH_ARRAY(x),
               (DATA_TYPE*)POLYBENCH_ARRAY(y),
               (DATA_TYPE*)POLYBENCH_ARRAY(tmp));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(y)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(y);
  POLYBENCH_FREE_ARRAY(tmp);

  return 0;
}
