from exo.libs.memories import DRAM
from exo.API_scheduling import *

# Tile size for the column dimension (n). This is a tuning knob:
# increase/decrease based on the target cache hierarchy.
TJ = 64

@proc
def kernel_atax(
    m: size,
    n: size,
    A: DATA_TYPE[m, n] @ DRAM,
    x: DATA_TYPE[n] @ DRAM,
    y: DATA_TYPE[n] @ DRAM,
    tmp: DATA_TYPE[m] @ DRAM,
):
    # 1) Initialize y to zero.
    #    Each iteration writes a distinct y[i], so this loop is
    #    embarrassingly parallel and will later be parallelized.
    for i in seq(0, n):
        y[i] = 0.0

    # 2) Main fused computation:
    #    For each row i:
    #      tmp[i] = sum_j A[i,j] * x[j]
    #      y[j]  += A[i,j] * tmp[i]
    #
    #    This matches the original PolyBench/ATAx kernel:
    #      tmp = A * x
    #      y   = A^T * tmp
    for i in seq(0, m):
        tmp[i] = 0.0

        # Accumulate tmp[i] = A[i, :] * x[:]
        for j in seq(0, n):
            tmp[i] += A[i, j] * x[j]

        # Accumulate y[:] += A[i, :] * tmp[i]
        for j in seq(0, n):
            y[j] += A[i, j] * tmp[i]


