/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

# Core Exo imports
from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# -----------------------------------------------------------------------------
# Baseline ATAX kernel
# -----------------------------------------------------------------------------
# Computes:
#   tmp[i] = sum_j A[i, j] * x[j]
#   y[j]   = sum_i A[i, j] * tmp[i]
#
# This matches the standard PolyBench ATAX kernel:
#   y = A^T * (A * x)
#
# TI and TJ are tiling parameters exposed as size arguments so they can be
# specialized (via partial_eval) for different cache hierarchies.
# -----------------------------------------------------------------------------
@proc
def kernel_atax(
    m: size,
    n: size,
    A: DATA_TYPE[m, n] @ DRAM,
    x: DATA_TYPE[n] @ DRAM,
    y: DATA_TYPE[n] @ DRAM,
    tmp: DATA_TYPE[m] @ DRAM,
    TI: size,     # tile size in the i (row) dimension
    TJ: size,     # tile size in the j (column) dimension
):
    assert m > 0
    assert n > 0
    assert TI > 0
    assert TJ > 0

    # Initialize y to zero
    for j in seq(0, n):
        y[j] = 0.0

    # Compute tmp = A * x and y = A^T * tmp
    for i in seq(0, m):
        tmp[i] = 0.0

        # tmp[i] = sum_j A[i, j] * x[j]
        for j in seq(0, n):
            tmp[i] += A[i, j] * x[j]

        # y[j] += A[i, j] * tmp[i]
        for j in seq(0, n):
            y[j] += A[i, j] * tmp[i]

# -----------------------------------------------------------------------------
# Scheduling: tiling in i and j
#
#  - We specialize TI and TJ to concrete constants using partial_eval; this
#    removes them from the final signature while keeping them easy to retune.
#  - We then tile the outer i-loop and all inner j-loops using divide_loop.
#  - Tiling i improves temporal locality for rows of A and tmp.
#  - Tiling j improves cache locality and exposes regular inner loops that
#    compilers can easily auto-vectorize.
#
# NOTE: The tiling factors below are chosen for a modern x64 with sizeable
# L1/L2 caches; they can be retuned by changing TI_VAL and TJ_VAL.
# -----------------------------------------------------------------------------

# Keep a handle to the original, purely algorithmic kernel
kernel_atax_baseline = kernel_atax

# Tunable tiling parameters (compile-time constants)
TI_VAL = 32    # tile size in i (rows of A / entries of tmp)
TJ_VAL = 256   # tile size in j (columns of A / entries of x and y)

# Partially evaluate the kernel with concrete tile sizes.
# After this, TI and TJ are constants and disappear from the argument list.
kernel_atax = kernel_atax_baseline.partial_eval(TI=TI_VAL, TJ=TJ_VAL)

# Tile the i-loop: creates outer io and inner ii loops.
# This preserves the original computation order within each i,
# but groups rows of A and elements of tmp into tiles of size TI_VAL.
kernel_atax = divide_loop(kernel_atax, "i", TI_VAL, ("io", "ii"), tail="guard")

# Tile all j-loops with the same TJ_VAL factor.
# We obtain all j-loops *after* tiling i so we cover:
#   - the initialization loop over y
#   - the j-loop used to form tmp
#   - the j-loop used to update y
# For each original j-loop we apply divide_loop once; implicit cursor
# forwarding ensures we always target the correct loop in the latest
# version of the procedure.
j_loops = kernel_atax.find_all("for j in _:_")
for j_loop in j_loops:
    kernel_atax = divide_loop(kernel_atax, j_loop, TJ_VAL, ("jo", "ji"),
                              tail="guard")

# At this point, `kernel_atax` is a tiled, cache-friendly implementation
# of ATAX with the same interface as the original baseline kernel:
#   (m, n, A, x, y, tmp)
# -----------------------------------------------------------------------------
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, M, N, m, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(tmp, DATA_TYPE, M, m);

  /* Initialize array(s). */
  init_array (m, n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(x));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten views to raw pointers. */
  kernel_atax (/*ctxt=*/NULL, m, n,
               (DATA_TYPE*)POLYBENCH_ARRAY(A),
               (DATA_TYPE*)POLYBENCH_ARRAY(x),
               (DATA_TYPE*)POLYBENCH_ARRAY(y),
               (DATA_TYPE*)POLYBENCH_ARRAY(tmp));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
