/**
 * Exo ATAX driver: mirrors PolyBench/C atax.c but calls the Exo-generated kernel.
 */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "atax.h"

/* Include the Exo-generated kernel header. */
#include "generated/atax/atax.h"


/* Array initialization. */
static
void init_array (int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n))
{
  int i, j;
  DATA_TYPE fn;
  fn = (DATA_TYPE)n;

  for (i = 0; i < n; i++)
      x[i] = 1 + (i / fn);
  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++)
      A[i][j] = (DATA_TYPE) ((i+j) % n) / (5*m);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(y,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("y");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, y[i]);
  }
  POLYBENCH_DUMP_END("y");
  POLYBENCH_DUMP_FINISH;
}

/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Tunable tile sizes for cache/blocking. These can be adjusted to match
# the target machine's cache hierarchy.
TILE_J = 64  # tile size along the N dimension (columns of A, entries of x/y)
TILE_I = 32  # tile size along the M dimension (rows of A, entries of tmp)


@proc
def atax_base(
    m: size,
    n: size,
    A: DATA_TYPE[m, n] @ DRAM,
    x: DATA_TYPE[n] @ DRAM,
    y: DATA_TYPE[n] @ DRAM,
    tmp: DATA_TYPE[m] @ DRAM,
):
    # Phase 1: tmp = A * x
    #   tmp[i] = sum_j A[i, j] * x[j]
    for i in seq(0, m):
        tmp[i] = 0.0
        for j in seq(0, n):
            tmp[i] += A[i, j] * x[j]

    # Phase 2: y = A^T * tmp
    #   y[j] = sum_i A[i, j] * tmp[i]
    #
    # This is mathematically equivalent to the original PolyBench
    # atax kernel, which zeroes y and then performs:
    #   for i:
    #     for j:
    #       y[j] += A[i, j] * tmp[i]
    #
    # Here we instead iterate j on the outside. This preserves the
    # mathematical result while exposing parallelism across j.
    for j in seq(0, n):
        y[j] = 0.0
        for i in seq(0, m):
            y[j] += A[i, j] * tmp[i]


def schedule_atax():
    p = atax_base

    # --- Phase 1 scheduling: tmp = A * x ---------------------------------
    # Tile the inner j loop to improve locality on A's rows and x.
    # Each tile touches a contiguous block of x[j] and A[i, j].
    j_tmp = p.find_loop("j #0")
    p = divide_loop(p, j_tmp, TILE_J, ("jo", "ji"), tail="guard")

    # --- Phase 2 scheduling: y = A^T * tmp --------------------------------
    # Tile the inner i loop to improve locality over tmp[i] and A[i, j]
    # for each fixed j. This keeps a small band of rows in cache.
    i_y = p.find_loop("i #1")
    p = divide_loop(p, i_y, TILE_I, ("io", "ii"), tail="guard")

    # Parallelize the outer j loop of phase 2. Each iteration operates
    # on a distinct y[j], so there are no cross-iteration write conflicts.
    j_y = p.find_loop("j #1")
    p = parallelize_loop(p, j_y)

    # Simplify the resulting code (clean up guards, algebra, etc.).
    p = simplify(p)

    return p


# Expose the scheduled kernel under the name used by the C driver.
kernel_atax = schedule_atax()
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, M, N, m, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(tmp, DATA_TYPE, M, m);

  /* Initialize array(s). */
  init_array (m, n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(x));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten views to raw pointers. */
  kernel_atax (/*ctxt=*/NULL, m, n,
               (DATA_TYPE*)POLYBENCH_ARRAY(A),
               (DATA_TYPE*)POLYBENCH_ARRAY(x),
               (DATA_TYPE*)POLYBENCH_ARRAY(y),
               (DATA_TYPE*)POLYBENCH_ARRAY(tmp));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(y)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(y);
  POLYBENCH_FREE_ARRAY(tmp);

  return 0;
}
